const body = $input.item.json.body || $input.item.json;

const entry = (body.entry || [])[0];
const change = (entry?.changes || [])[0];
const value = change?.value;
const message = (value?.messages || [])[0];

if (!message) return [{ json: { skip: true } }];

const telefono = String(message.from || '');
const texto = message.text?.body || '';
const messageId = message.id || '';
const timestamp = String(message.timestamp || Date.now());
const nombreContacto = (value?.contacts || [])[0]?.profile?.name || '';
const phoneNumberId = String(value?.metadata?.phone_number_id || '');

const tipoMensaje = message.type || 'text';
let mediaId = null, mimeType = null, mediaCaption = '';
if (['image','audio','document','video'].includes(tipoMensaje)) {
  const mediaObj = message[tipoMensaje] || {};
  mediaId = mediaObj.id || null;
  mimeType = mediaObj.mime_type || null;
  mediaCaption = mediaObj.caption || '';
}

return [{ json: {
  telefono,
  texto,
  messageId,
  timestamp,
  nombreContacto,
  canal: 'whatsapp',
  usuarioId: telefono,
  resolveKey: phoneNumberId,
  resolveType: 'wa',
  tipoMensaje,
  mediaId,
  mimeType,
  mediaCaption,
  skip: false
} }];

const body = $input.item.json.body || $input.item.json;

let canal = 'facebook_dm';
let usuarioId = '';
let texto = '';
let messageId = '';
let timestamp = String(Date.now());
let nombreContacto = '';

if (body.object === 'instagram') {
  canal = 'instagram_dm';
  const entry = (body.entry || [])[0] || {};
  const messaging = (entry.messaging || [])[0] || {};
  if (messaging.message) {
    usuarioId = messaging.sender?.id || '';
    texto = messaging.message?.text || '';
    messageId = messaging.message?.mid || '';
  } else {
    const ch = (entry.changes || [])[0] || {};
    const val = ch.value || {};
    usuarioId = val.from?.id || '';
    texto = val.text || '';
    messageId = val.id || '';
  }
} else {
  canal = 'facebook_dm';
  const entry = (body.entry || [])[0] || {};
  const messaging = (entry.messaging || [])[0] || {};
  usuarioId = messaging.sender?.id || '';
  texto = messaging.message?.text || '';
  messageId = messaging.message?.mid || '';
  timestamp = String(messaging.timestamp || Date.now());
}

if (!texto.trim() || !usuarioId) return [{ json: { skip: true } }];

const pageId = String((body.entry || [])[0]?.id || '');

return [{ json: {
  telefono: 'fbig_' + usuarioId,
  pageId,
  texto,
  messageId,
  timestamp,
  nombreContacto,
  canal,
  usuarioId,
  resolveKey: pageId,
  resolveType: 'page',
  skip: false
} }];

const config = $('⚙️ Config G54').item.json;

let resolveKey = '';
let resolveType = '';
let msgData = null;

try {
  const waData = $('🔧 Extraer Mensaje WA').item.json;
  if (waData && !waData.skip) { resolveKey = String(waData.resolveKey || ''); resolveType = 'wa'; msgData = waData; }
} catch(e) {}

if (!resolveKey) {
  try {
    const socialData = $('🔧 Extraer Mensaje FB/IG DM').item.json;
    if (socialData && !socialData.skip) { resolveKey = String(socialData.resolveKey || ''); resolveType = 'page'; msgData = socialData; }
  } catch(e) {}
}

let queryCompanyId = '';
try { queryCompanyId = String($('📲 Webhook WhatsApp').item.json.query?.company || ''); } catch(e) {}
if (!queryCompanyId) {
  try { queryCompanyId = String($('📲 Webhook FB/IG DM').item.json.query?.company || ''); } catch(e) {}
}

// Telegram: G54 ya nos da el company_id real en el relevo (empresa_id) — no hace falta resolverlo por HTTP
if (!queryCompanyId) {
  try {
    const tgData = $('🔧 Extraer Mensaje Telegram').item.json;
    if (tgData && !tgData.skip && tgData.empresaId) { queryCompanyId = String(tgData.empresaId); resolveType = 'telegram'; msgData = tgData; }
  } catch(e) {}
}

const resolverUrl = (!queryCompanyId && resolveKey)
  ? config.G54_BASE_URL + '/api/n8n/' + (resolveType === 'wa' ? 'wa-phones' : 'pages') + '/' + resolveKey
  : '';

return [{ json: { ...config, resolveKey, resolveType, resolverUrl, queryCompanyId, _msgData: msgData } }];

const base = $('🔍 Preparar Resolución').item.json;
let resolved = {};
try {
  const r = $('🏢 Resolver Empresa (G54)').item.json;
  if (r && r.company_id && !r.error && !r.message) resolved = r.data || r;
} catch(e) {}

const company_id = String(base.queryCompanyId || resolved.company_id || '');
const fb_access_token = resolved.fb_access_token || '';

return [{ json: {
  G54_BASE_URL: base.G54_BASE_URL,
  G54_N8N_TOKEN: base.G54_N8N_TOKEN,
  G54_AGENT_TOKEN: base.G54_AGENT_TOKEN,
  G54_COMPANY_ID: company_id,
  FB_ACCESS_TOKEN: fb_access_token
} }];

// Determine which extractor has the message (WA, Social o Telegram)
let msgData;
try { msgData = $('🔧 Extraer Mensaje WA').item.json; } catch(e) {}
if (!msgData || msgData.skip) {
  try { msgData = $('🔧 Extraer Mensaje FB/IG DM').item.json; } catch(e) {}
}
if (!msgData || msgData.skip) {
  try { msgData = $('🔧 Extraer Mensaje Telegram').item.json; } catch(e) {}
}

let texto = msgData?.texto || '';
try {
  const medioResult = $('🔧 Combinar Texto de Medio').first().json;
  if (medioResult && medioResult.texto) texto = medioResult.texto;
} catch (e) { /* no vino por la rama de medios, se usa el texto original */ }
const telefono = msgData?.telefono || '';
const canal = msgData?.canal || 'whatsapp';
const nombreContacto = msgData?.nombreContacto || '';
const usuarioId = msgData?.usuarioId || '';
const messageId = msgData?.messageId || '';
// Telegram — solo presentes si msgData vino de esa rama, undefined en WA/Social sin ningún efecto
const chatId = msgData?.chatId;
const conversationId = msgData?.conversationId;
const contactIdTelegram = msgData?.contactId;
const empresaIdTelegram = msgData?.empresaId;

// Empresa
const empresaRaw = $('🏢 Obtener Empresa G54').item.json;
const empresa = empresaRaw?.data || empresaRaw || {};
const empresa_nombre = empresa.name || 'Empresa';
const empresa_descripcion = empresa.description || '';
const empresa_ciudad = empresa.base_city || '';
const empresa_web = empresa.website || '';
const emailsVendedor = (empresa.emails || []).join(',') || '';

// WA Config — para WhatsApp se resuelve por teléfono (trae wa_access_token real para enviar).
// Para Social/Telegram no existe ningún dato de teléfono real — se resuelve por empresa vía
// sesión (⚙️ Obtener WA Config (Empresa)), que no trae el token de WA pero sí el system_prompt,
// catálogo, FAQs y mensajes reales configurados por el cliente, en vez de caer siempre al
// respaldo genérico. Se intenta primero el resultado por teléfono (real en el canal WA);
// si no vino (no corrió esa rama) o vino vacío, se cae al resultado por empresa.
let waConfig = {};
try {
  const waConfigRaw = $('⚙️ Obtener WA Config G54').item.json;
  const d = waConfigRaw?.data || waConfigRaw;
  if (d && d.system_prompt) waConfig = d;
} catch(e) {}
if (!waConfig.system_prompt) {
  try {
    const empConfigRaw = $('⚙️ Obtener WA Config (Empresa)').item.json;
    const d2 = empConfigRaw?.data || empConfigRaw;
    if (d2 && d2.system_prompt) waConfig = d2;
  } catch(e) {}
}

const wa_access_token = waConfig.wa_access_token || '';
const phone_number_id = waConfig.phone_number_id || '';
const auto_reply = waConfig.auto_reply !== undefined ? waConfig.auto_reply : true;
const nombre_agente = waConfig.agent_name || 'Agente';
// G54 devuelve estos campos como msg_bienvenida / msg_followup_24h / msg_followup_72h —
// nombres reales confirmados en vivo, no welcome_message/followup_24h como se leía antes.
const bienvenida = waConfig.msg_bienvenida || waConfig.welcome_message || `Hola 👋 Soy ${nombre_agente}, el asistente de ${empresa_nombre}. ¿En qué te puedo ayudar?`;
const instruccionesIA = waConfig.ia_instructions || '';
const promptTemplate = waConfig.system_prompt || `Eres {{AGENTE}}, asistente virtual de {{EMPRESA}}. Ayuda al cliente a conocer los productos y servicios disponibles. Catálogo:\n{{CATALOGO}}\n{{INSTRUCCIONES}}`;
const followup24 = waConfig.msg_followup_24h || waConfig.followup_24h || '';
const followup72 = waConfig.msg_followup_72h || waConfig.followup_72h || '';

// Productos
const productosRaw = $('📦 Obtener Productos G54').item.json;
const productos = productosRaw?.data || [];
const catalogoProductos = productos.map(p => {
  const nombre = p.name || '';
  const desc = p.description || '';
  const kw = (p.keywords || []).join(', ');
  return `• ${nombre}: ${desc}${kw ? ' [' + kw + ']' : ''}`;
}).filter(l => l.length > 3).join('\n');

// Lead existente
const leadRaw = $('📋 Buscar Lead Existente').item.json;
const leads = leadRaw?.data || [];
const leadExistente = leads[0] || null;
const leadId = leadExistente?.id || null;
// Parse __DATOS__ marker from G54 historial for datos persistence
const rawHistorial = leadExistente?.historial || '';
const historialLines = rawHistorial.split('\n');
let leadDatos = {};
const datosLine = [...historialLines].reverse().find(l => l.includes('[__DATOS__]'));
if (datosLine) {
  try { leadDatos = JSON.parse(datosLine.replace(/^.*\[__DATOS__\]/, '')); } catch(e) {}
}
const historial = historialLines.filter(l => !l.includes('[__DATOS__]')).join('\n');
const estado = leadExistente?.estado || 'Nuevo';
const esNuevo = !leadId;

// datos_actualizados is a free object — the prompt defines what to collect
// We carry over whatever was stored previously and let AI merge
const datosRecolectados = typeof leadDatos === 'object' ? leadDatos : {};

// Build prompt — replace placeholders
const promptSistema = promptTemplate
  .replace(/\{\{AGENTE\}\}/g, nombre_agente)
  .replace(/\{\{EMPRESA\}\}/g, empresa_nombre)
  .replace(/\{\{CATALOGO\}\}/g, catalogoProductos || '(sin catálogo disponible)')
  .replace(/\{\{INSTRUCCIONES\}\}/g, instruccionesIA ? 'Instrucciones adicionales:\n' + instruccionesIA : '')
  .trim();

// Hora local — se lee la zona horaria real de la empresa desde G54.
// Si no está configurada, NUNCA se asume la de otra empresa (ni Miami ni ninguna otra) —
// se usa UTC como neutral y el Vigía G54 alerta aparte para que se configure (ver workflow-vigia-g54.json).
let h;
try {
  const tz = $('🕐 Resolver Timezone Empresa').item.json.empresa_timezone;
  if (tz) {
    h = parseInt(new Intl.DateTimeFormat('en-US', { timeZone: tz, hour: 'numeric', hour12: false }).format(new Date()), 10);
  } else {
    throw new Error('sin timezone resuelta');
  }
} catch (e) {
  h = new Date().getUTCHours();
}
const saludoHora = h >= 6 && h < 12 ? 'buenos días' : h >= 12 && h < 19 ? 'buenas tardes' : 'buenas noches';

return [{ json: {
  // Message
  texto,
  telefono,
  canal,
  nombreContacto,
  usuarioId,
  messageId,
  // Telegram (undefined en WA/Social, sin efecto)
  chatId,
  conversationId,
  contactIdTelegram,
  empresaIdTelegram,
  // Context
  promptSistema,
  nombre_agente,
  empresa_nombre,
  empresa_descripcion,
  empresa_ciudad,
  empresa_web,
  emailsVendedor,
  bienvenida,
  followup24,
  followup72,
  catalogoProductos,
  // WA credentials (from G54 config)
  wa_access_token,
  phone_number_id,
  auto_reply,
  // Lead
  leadId,
  estado,
  historial,
  datosRecolectados,
  esNuevo,
  saludoHora
} }];

