={{ (() => {
const escalada = $json.escalada;
const clasificacion = $json.clasificacion;
const esConsulta = escalada && clasificacion !== 'caliente';

const d = $json.datosRecolectados || {};
const tel = $json.telefono || '';
const canal = $json.canal || '';
const nombre = $json.nombreContacto || 'No disponible';
const empresa = $json.empresa_nombre || 'Growth54';
const resumen = $json.resumenLead || '';

const humanizar = (k) => k.replace(/_/g, ' ').replace(/^./, c => c.toUpperCase());

const filasDatos = Object.entries(d)
  .filter(([k, v]) => v !== null && v !== undefined && v !== '')
  .map(([k, v]) => '<tr><td style="padding:6px 0;font-size:14px;color:#374151;">' + humanizar(k) + ': <strong>' + v + '</strong></td></tr>')
  .join('');

const esWhatsApp = /whatsapp|wa$/i.test(canal) || (!/dm|facebook|instagram/i.test(canal) && tel);
const botonWA = esWhatsApp
  ? '<tr><td style="padding-top:16px;"><a href="https://wa.me/' + tel.replace(/[^0-9]/g,'') + '" style="display:inline-block;background:#25D366;color:#fff;padding:10px 18px;border-radius:6px;text-decoration:none;font-size:14px;">Responder por WhatsApp</a></td></tr>'
  : '';

const badgeColor = esConsulta ? 'rgba(251,191,36,.24)' : 'rgba(239,68,68,.22)';
const badgeTexto = esConsulta ? '💬 Necesita respuesta de un agente' : '🔥 Lead caliente — requiere seguimiento hoy';
const titulo = esConsulta ? 'Consulta sin responder' : ('Lead calificado — ' + empresa);

return '<table style="max-width:520px;font-family:Arial,sans-serif;">'
  + '<tr><td style="background:' + badgeColor + ';padding:8px 12px;font-size:13px;font-weight:600;">' + badgeTexto + '</td></tr>'
  + '<tr><td style="padding-top:8px;font-size:18px;font-weight:700;color:#111827;">' + titulo + '</td></tr>'
  + '<tr><td style="padding-top:16px;"><table width="100%" cellpadding="0" cellspacing="0">'
  + '<tr><td style="padding:6px 0;font-size:14px;color:#374151;">👤 ' + nombre + '</td></tr>'
  + '<tr><td style="padding:6px 0;font-size:14px;color:#374151;">📞 ' + tel + '</td></tr>'
  + '<tr><td style="padding:6px 0;font-size:14px;color:#374151;">💬 Canal: ' + canal + '</td></tr>'
  + '</table></td></tr>'
  + (filasDatos ? '<tr><td style="padding-top:16px;"><table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #f3f4f6;border-radius:8px;padding:12px;">' + filasDatos + '</table></td></tr>' : '')
  + (resumen ? '<tr><td style="padding-top:14px;font-size:13px;color:#6b7280;"><strong>Resumen:</strong> ' + resumen + '</td></tr>' : '')
  + botonWA
  + '<tr><td style="padding-top:20px;font-size:12px;color:#9ca3af;">Generado automáticamente por Sales AI Motor · Growth54</td></tr>'
  + '</table>';
})() }}

