={{ JSON.stringify({
  empresa_id: Number($('🏢 Aplicar Config Empresa').item.json.G54_COMPANY_ID),
  phone: $json.telefono,
  contact_name: $json.nombreContacto || '',
  clasificacion: $json.clasificacion || 'frio',
  messages: [
    ...($json.nuevoHistorial || '').split('\n').filter(l => l.trim() && l.includes('] ')).map(l => {
    const content = l.replace(/^\[.*?\]\s*/, '');
    const isBot = content.startsWith('Bot:') || content.startsWith('Agente:');
    return { rol: isBot ? 'bot' : 'user', contenido: content.replace(/^(Bot|Agente|Cliente):\s*/, ''), isBot };
  }).filter(m => m.contenido && ($('🔧 Preparar Contexto IA').item.json.auto_reply !== false || !m.isBot)).map(m => ({ rol: m.rol, contenido: m.contenido })),
    { rol: 'bot', contenido: '[__DATOS__]' + JSON.stringify($json.datosRecolectados || {}) }
  ]
}) }}

