const configs = $('⚙️ Config G54 Follow-up').all();
const leadsPorEmpresa = $('📋 Obtener Leads Sin Respuesta').all();
const waConfigsPorEmpresa = $('⚙️ Obtener WA Config Follow-up').all();

const now = new Date();
const results = [];

for (let i = 0; i < configs.length; i++) {
  const cfg = configs[i].json;
  const leadsRaw = leadsPorEmpresa[i] ? leadsPorEmpresa[i].json : {};
  const leads = leadsRaw?.data || leadsRaw?.records || [];

  let waConfig = {};
  try { waConfig = (waConfigsPorEmpresa[i] ? waConfigsPorEmpresa[i].json : {})?.data || {}; } catch(e) {}

  const followup24 = waConfig.followup_24h || 'Hola 👋 ¿Sigues necesitando ayuda? Aquí estamos para asistirte.';
  const followup72 = waConfig.followup_72h || 'Seguimos disponibles cuando lo necesites 👍';
  const wa_access_token = waConfig.wa_access_token || '';
  const phone_number_id = waConfig.phone_number_id || '';

  for (const lead of leads) {
    const ultimaActividad = new Date(lead.ultima_actividad || lead.created_at || 0);
    const horasDiff = (now - ultimaActividad) / (1000 * 60 * 60);
    let tipoFollowup = null;
    if (horasDiff >= 72) tipoFollowup = '72h';
    else if (horasDiff >= 24) tipoFollowup = '24h';
    if (!tipoFollowup) continue;

    const telefono = (lead.phone || '').replace(/^\+/, '');
    if (!telefono || telefono.startsWith('fbig_')) continue;

    results.push({ json: {
      leadId: lead.id,
      telefono,
      nombre: lead.name || '',
      tipoFollowup,
      estado: lead.estado || '',
      mensajeFollowup: tipoFollowup === '24h' ? followup24 : followup72,
      wa_access_token,
      phone_number_id,
      // Contexto de empresa propagado explícitamente — evita que los nodos downstream
      // tengan que volver a buscar "la" empresa vía .item después de este fan-out
      // (mismo tipo de bug de .item/.first() ya corregido antes en Distribution AI/Telegram).
      G54_BASE_URL: cfg.G54_BASE_URL,
      G54_AGENT_TOKEN: cfg.G54_AGENT_TOKEN,
      G54_COMPANY_ID: cfg.G54_COMPANY_ID,
      G54_MASTER_EMAIL: cfg.G54_MASTER_EMAIL,
      G54_MASTER_PASSWORD: cfg.G54_MASTER_PASSWORD
    } });
  }
}

return results.length ? results : [{ json: { skip: true } }];

